// Extrae el primer mensaje de texto del payload de Meta, si existe.
// Eventos de status (delivered/read) o mensajes que no son de texto (audio, imagen, etc.)
// no traen messages[0].type === 'text' y deben ignorarse en este flujo v1.
const body = $input.first().json.body ?? $input.first().json;

const entry = body?.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

const phoneNumberId = value?.metadata?.phone_number_id ?? null;
const isTextMessage = Boolean(message && message.type === 'text' && message.text?.body);

return [
  {
    json: {
      isTextMessage,
      phoneNumberId,
      customerPhone: message?.from ?? null,
      messageText: isTextMessage ? message.text.body : null,
      rawValue: value ?? null
    }
  }
];

// Combina el resultado de bot_get_menu con los datos del mensaje original
// (telefono del cliente y texto) en un solo objeto para los nodos siguientes.
const menu = $input.first().json;
const original = $('Extraer mensaje de texto').first().json;

return [
  {
    json: {
      restaurant: menu.restaurant,
      categories: menu.categories,
      products: menu.products,
      phoneNumberId: original.phoneNumberId,
      customerPhone: original.customerPhone,
      messageText: original.messageText
    }
  }
];

// Memoria de conversacion MUY simple, en memoria del proceso de n8n (workflowStaticData),
// keyeada por numero de telefono del cliente. Limitacion conocida (ver README):
// se pierde si n8n se reinicia o si corre en mas de una instancia/worker.
const staticData = $getWorkflowStaticData('global');
staticData.conversations = staticData.conversations || {};
staticData.customerProfiles = staticData.customerProfiles || {};

const input = $input.first().json;
const phone = input.customerPhone;
const history = staticData.conversations[phone] || [];

// Guarda el mensaje entrante del cliente en el historial antes de llamar al LLM.
history.push({ role: 'customer', text: input.messageText, at: new Date().toISOString() });
// Conserva solo los ultimos 12 turnos para no inflar el prompt indefinidamente.
staticData.conversations[phone] = history.slice(-12);

const attempts = staticData.failedAttempts || {};
const failedAttempts = attempts[phone] || 0;
// Nombre/correo ya capturados en turnos anteriores de esta misma conversacion.
const profile = staticData.customerProfiles[phone] || { name: '', email: '' };

return [
  {
    json: {
      ...input,
      conversationHistory: staticData.conversations[phone],
      failedAttempts,
      customerName: profile.name,
      customerEmail: profile.email
    }
  }
];

// Construye el system prompt dinamico para el LLM: datos del negocio, extraPrompt
// del admin, catalogo completo serializado, historial de conversacion reciente,
// fecha/hora actual, datos del cliente ya conocidos, y las reglas estrictas de
// formato de salida JSON.
const data = $input.first().json;
const restaurant = data.restaurant;
const categories = data.categories || [];
const products = data.products || [];

const catalogLines = categories.map((cat) => {
  const items = products
    .filter((p) => p.categoryId === cat.id)
    .map((p) => `    - id: ${p.id} | ${p.name} | RD$ ${p.price}${p.description ? ' | ' + p.description : ''}`)
    .join('\n');
  return `  ${cat.name}:\n${items || '    (sin productos disponibles)'}`;
}).join('\n');

const historyText = (data.conversationHistory || [])
  .map((turn) => `${turn.role === 'customer' ? 'Cliente' : 'Bot'}: ${turn.text}`)
  .join('\n');

// El LLM no tiene reloj propio: hay que decirle la fecha/hora real para que pueda
// aplicar un horario de atencion que el admin describa en texto libre en extraPrompt.
const now = new Date();
const nowText = now.toLocaleString('es-DO', { timeZone: 'America/Santo_Domingo', dateStyle: 'full', timeStyle: 'short' });

const systemPrompt = `Eres el asistente de pedidos por WhatsApp del restaurante "${restaurant.name}".
Direccion: ${restaurant.address || 'no especificada'}
Telefono: ${restaurant.phone || 'no especificado'}
Instrucciones del negocio (horarios, promociones, tono, cuentas de pago, etc.): ${restaurant.extraPrompt || '(sin instrucciones adicionales)'}

FECHA Y HORA ACTUAL (zona horaria Republica Dominicana): ${nowText}

DATOS DEL CLIENTE YA CONOCIDOS EN ESTA CONVERSACION:
Nombre: ${data.customerName || '(desconocido, falta pedirlo)'}
Correo: ${data.customerEmail || '(desconocido, falta pedirlo)'}

CATALOGO DISPONIBLE (unicos productos que existen, con su id real -- nunca inventes productos, precios o ids fuera de esta lista):
${catalogLines}

HISTORIAL RECIENTE DE LA CONVERSACION CON ESTE CLIENTE:
${historyText || '(primer mensaje de esta conversacion)'}

REGLAS:
1. Identifica si el cliente quiere hacer un pedido, esta haciendo una pregunta (horarios, menu, direccion, etc.) o quiere hablar con una persona.
2. Para resolver un pedido, mapea por nombre/parecido (fuzzy match) cada producto que menciona el cliente a un id real del catalogo. Nunca inventes un productId que no este en la lista.
3. Si el cliente menciona un producto pero NO dice la cantidad, NO asumas cantidad 1: responde con intent "chat" preguntando la cantidad de ese producto especifico.
4. Antes de poder usar intent "order" necesitas TODO esto: productos con cantidad clara, el nombre completo del cliente y su correo electronico. Si falta el nombre o el correo (revisa "DATOS DEL CLIENTE" arriba), usa intent "chat" y pidelo explicitamente -- nunca inventes un nombre o correo. En cuanto el cliente te de su nombre y/o correo, devuelvelos en los campos "customerName"/"customerEmail" de tu respuesta JSON, incluso si todavia faltan otros datos del pedido.
5. Si las instrucciones del negocio arriba indican un horario de atencion, compara ese horario contra la FECHA Y HORA ACTUAL. Si el restaurante esta cerrado en este momento, usa intent "chat" y explica amablemente que esta cerrado e indica el horario en que puede ordenar -- no continues hacia "order" aunque el cliente ya haya dado todos los demas datos.
6. Si tras un par de intentos no logras identificar que producto del catalogo quiere el cliente, o el cliente pide explicitamente hablar con una persona/agente/humano, usa intent "handoff" y explica el motivo en "reason" (usa uno de: no_entendido, cliente_pidio_humano, producto_no_encontrado).
7. Si es solo una pregunta (bebidas disponibles, horario, direccion, metodos de pago, etc.), respondela directamente con la info que ya tienes arriba, usando intent "chat", sin necesidad de crear pedido ni handoff.
8. "replyText" siempre debe tener el texto exacto que se le va a mandar al cliente por WhatsApp (en español, tono amable, conciso).
9. Responde SIEMPRE y UNICAMENTE con un JSON valido, sin texto adicional antes o despues, exactamente con esta forma:
{"intent": "chat" | "order" | "handoff", "replyText": "string", "items": [{"productId": "uuid", "quantity": 1, "notes": ""}], "reason": "string", "customerName": "string", "customerEmail": "string"}
Si no aplica "items", "reason", "customerName" o "customerEmail", devuelvelos como arreglo vacio [] o string vacio "" segun corresponda, pero no omitas las claves.`;

return [
  {
    json: {
      ...data,
      systemPrompt
    }
  }
];

// El AI Agent puede devolver el JSON envuelto en texto o con bloque ```json.
// Este nodo extrae y parsea el JSON de forma defensiva; si falla el parseo,
// trata el caso como 'no entendido' y fuerza un handoff en lugar de romper el flujo.
const agentOutput = $input.first().json.output ?? $input.first().json.text ?? '';
const previous = $('Construir system prompt').first().json;

function extractJson(raw) {
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try {
    return JSON.parse(match[0]);
  } catch {
    return null;
  }
}

const parsed = extractJson(agentOutput);

const staticData = $getWorkflowStaticData('global');
staticData.failedAttempts = staticData.failedAttempts || {};
staticData.customerProfiles = staticData.customerProfiles || {};
const phone = previous.customerPhone;

if (!parsed || !parsed.intent) {
  staticData.failedAttempts[phone] = (staticData.failedAttempts[phone] || 0) + 1;
  const tooManyAttempts = staticData.failedAttempts[phone] >= 3;
  return [
    {
      json: {
        ...previous,
        intent: tooManyAttempts ? 'handoff' : 'chat',
        replyText: tooManyAttempts
          ? 'Disculpa, no logro entender bien tu pedido. Ya avise a alguien del negocio para que te atienda en breve.'
          : 'Disculpa, no entendi bien eso. Puedes repetir tu pedido con mas detalle?',
        items: [],
        reason: 'no_entendido'
      }
    }
  ];
}

// Si el LLM resolvio bien la intencion, reinicia el contador de intentos fallidos.
if (parsed.intent !== 'handoff') {
  staticData.failedAttempts[phone] = 0;
}

// Conserva nombre/correo ya conocidos de turnos anteriores si el LLM no los repite ahora.
const profile = staticData.customerProfiles[phone] || { name: '', email: '' };
const customerName = (parsed.customerName || '').trim() || profile.name || '';
const customerEmail = (parsed.customerEmail || '').trim() || profile.email || '';
staticData.customerProfiles[phone] = { name: customerName, email: customerEmail };

// Guarda la respuesta del bot en el historial de conversacion.
staticData.conversations = staticData.conversations || {};
const history = staticData.conversations[phone] || [];
history.push({ role: 'bot', text: parsed.replyText, at: new Date().toISOString() });
staticData.conversations[phone] = history.slice(-12);

return [
  {
    json: {
      ...previous,
      intent: parsed.intent,
      replyText: parsed.replyText || '',
      items: Array.isArray(parsed.items) ? parsed.items : [],
      reason: parsed.reason || '',
      customerName,
      customerEmail
    }
  }
];

// bot_upsert_customer fallo (correo invalido, o el LLM aun no lo tiene). Se le pide
// al cliente que confirme nombre y correo antes de poder registrar el pedido.
const combined = $('Parsear salida del LLM').first().json;

return [
  {
    json: {
      phoneNumberId: combined.phoneNumberId,
      customerPhone: combined.customerPhone,
      replyText: 'No pude registrar tus datos de contacto. Puedes confirmarme de nuevo tu nombre completo y un correo electronico valido?'
    }
  }
];

// Arma el texto de confirmacion de pedido para el cliente, usando los nombres reales
// del catalogo (no los que escribio el cliente) y el total/numero de orden devueltos por bot_create_order.
const combined = $('Combinar menu + mensaje').first().json;
const order = $('Supabase: bot_create_order').first().json;
const productsById = Object.fromEntries((combined.products || []).map((p) => [p.id, p]));

const itemLines = (combined.items || [])
  .map((it) => `- ${it.quantity} x ${productsById[it.productId]?.name || 'producto'}`)
  .join('\n');

const total = new Intl.NumberFormat('es-DO', { style: 'currency', currency: 'DOP', minimumFractionDigits: 2 }).format(order.total || 0);

const replyText = `Listo! Tu pedido ${order.orderNumber} quedo registrado:\n${itemLines}\n\nTotal: ${total}\n\nGracias por tu compra en ${combined.restaurant.name}.`;

return [
  {
    json: {
      phoneNumberId: combined.phoneNumberId,
      customerPhone: combined.customerPhone,
      replyText
    }
  }
];

// bot_create_order fallo (400). Se le responde al cliente algo amable pidiendole
// que aclare el pedido, sin exponer detalles tecnicos del error.
const combined = $('Combinar menu + mensaje').first().json;

return [
  {
    json: {
      phoneNumberId: combined.phoneNumberId,
      customerPhone: combined.customerPhone,
      replyText: 'No pude registrar tu pedido tal como lo escribiste. Puedes confirmarme de nuevo, uno por uno, los productos y cantidades que deseas?'
    }
  }
];

// Mensaje al cliente avisando que pronto lo atendera una persona del negocio.
const combined = $('Combinar menu + mensaje').first().json;

return [
  {
    json: {
      phoneNumberId: combined.phoneNumberId,
      customerPhone: combined.customerPhone,
      replyText: 'Entendido. En breve alguien de nuestro equipo te va a contactar para ayudarte directamente. Gracias por tu paciencia!'
    }
  }
];

// intent = 'chat': se responde directo con el replyText que arma el LLM
// (pregunta de aclaracion, respuesta a una duda del menu/horario, etc.), sin tocar la base de datos.
const data = $input.first().json;

return [
  {
    json: {
      phoneNumberId: data.phoneNumberId,
      customerPhone: data.customerPhone,
      replyText: data.replyText
    }
  }
];
